/**
 * @ohos/dsh-ontology/store — SQLite-backed personal ontology.
 *
 * Design decisions that matter more than the SQL:
 *
 *   - `entity` is separate from `fact` so two people called "小李" do not
 *     collapse into one row, and a fact can point at either a literal or
 *     another entity (`relation` does the latter).
 *   - facts are superseded, never overwritten: `superseded_by` points at the
 *     replacement, `retired_at` marks a user deletion. History is how the
 *     model can tell "used to be true" from "is true".
 *   - `pinned` is derived from the predicate, not from the model's mood: an
 *     allergy is always injected, a project note is not.
 *   - the vocabulary is code (`vocab.js`), so an unknown predicate fails with
 *     the list instead of silently creating a junk graph.
 *
 * Everything here is synchronous (`node:sqlite`); callers keep queries small
 * and indexed. The store never logs; the plugin owns diagnostics.
 */
import { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";
import { predicateSpec, predicatesMatching, suggestPredicate, ENTITY_KINDS, PREDICATE_NAMES } from "./vocab.js";

/** Stable error codes surfaced to the tool layer. */
export class OntologyError extends Error {
	/**
	 * @param {string} message - human-readable detail.
	 * @param {'BAD_INPUT'|'UNKNOWN_PREDICATE'|'UNKNOWN_ENTITY'|'NOT_FOUND'} code - stable code.
	 */
	constructor(message, code) {
		super(message);
		this.name = "OntologyError";
		this.code = code;
	}
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS entity (
  id TEXT PRIMARY KEY,
  kind TEXT NOT NULL,
  name TEXT NOT NULL,
  aliases TEXT NOT NULL DEFAULT '[]',
  created_at TEXT NOT NULL,
  merged_into TEXT
) STRICT;

CREATE TABLE IF NOT EXISTS fact (
  id TEXT PRIMARY KEY,
  subject TEXT NOT NULL REFERENCES entity(id),
  predicate TEXT NOT NULL,
  object TEXT,
  object_kind TEXT NOT NULL,
  qualifier TEXT,
  confidence REAL NOT NULL DEFAULT 1,
  source TEXT NOT NULL,
  source_kind TEXT NOT NULL DEFAULT 'model',
  source_ref TEXT,
  status TEXT NOT NULL DEFAULT 'asserted',
  confirmed_at TEXT,
  observed_at TEXT NOT NULL,
  valid_from TEXT NOT NULL,
  valid_to TEXT,
  recorded_at TEXT NOT NULL,
  superseded_by TEXT,
  superseded_at TEXT,
  retired_at TEXT,
  pinned INTEGER NOT NULL DEFAULT 0
) STRICT;

CREATE TABLE IF NOT EXISTS meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
) STRICT;

CREATE INDEX IF NOT EXISTS fact_subject ON fact(subject, predicate);
CREATE INDEX IF NOT EXISTS fact_live ON fact(predicate) WHERE superseded_by IS NULL AND retired_at IS NULL;
CREATE INDEX IF NOT EXISTS fact_observed ON fact(observed_at);
CREATE INDEX IF NOT EXISTS fact_valid_from ON fact(valid_from);
CREATE INDEX IF NOT EXISTS fact_recorded_at ON fact(recorded_at);
`;

/**
 * Semantic views. `v_live_fact` is the single definition of "current": every
 * read that means "what is true now" goes through it instead of repeating the
 * two-column predicate in a dozen queries. `v_entity_edge` turns entity-valued
 * facts into graph edges for `related`.
 *
 * `status = 'proposed'` never counts as live: the future auto-capture path can
 * write candidates without making them visible or injectable until the user
 * confirms them.
 */
const VIEWS = `
DROP VIEW IF EXISTS v_entity_edge;
DROP VIEW IF EXISTS v_live_fact;
CREATE VIEW v_live_fact AS
SELECT f.* FROM fact f
WHERE f.superseded_by IS NULL
  AND f.retired_at IS NULL
  AND f.status <> 'proposed';
CREATE VIEW v_entity_edge AS
SELECT f.subject AS from_id, f.predicate, f.object AS to_id, f.qualifier
FROM v_live_fact f
WHERE f.object_kind = 'entity';
`;

/** Joined projection every read uses. */
const SELECT_FACT = `
SELECT f.*,
       s.name AS subject_name,
       s.kind AS subject_kind,
       o.name AS object_name
FROM fact f
JOIN entity s ON s.id = f.subject
LEFT JOIN entity o ON o.id = f.object AND f.object_kind = 'entity'
`;

/** Same projection, but only facts that are true now. */
const SELECT_LIVE_FACT = `
SELECT f.*,
       s.name AS subject_name,
       s.kind AS subject_kind,
       o.name AS object_name
FROM v_live_fact f
JOIN entity s ON s.id = f.subject
LEFT JOIN entity o ON o.id = f.object AND f.object_kind = 'entity'
`;

/** @param {string} prefix - id prefix. @returns {string} short opaque id. */
function newId(prefix) {
	return `${prefix}_${randomUUID().replaceAll("-", "").slice(0, 12)}`;
}

/** @returns {string} ISO timestamp. */
function nowIso() {
	return new Date().toISOString();
}

/** @param {string} value - candidate date. @returns {string} normalized date. */
function normalizeDate(value) {
	const trimmed = value.trim();
	if (!/^(\d{4}-)?\d{2}-\d{2}$/.test(trimmed)) {
		throw new OntologyError(`date must be YYYY-MM-DD or MM-DD, got ${JSON.stringify(value)}`, "BAD_INPUT");
	}
	return trimmed;
}

/**
 * Normalize a user/model instant to a full ISO timestamp. Date-only input is
 * anchored at UTC midnight so lexicographic comparisons stay consistent.
 * @param {unknown} value - candidate instant.
 * @param {string} fallback - used when empty.
 * @returns {string} ISO timestamp.
 */
function normalizeInstant(value, fallback) {
	if (typeof value !== "string" || value.trim().length === 0) return fallback;
	const trimmed = value.trim();
	if (/^\d{4}-\d{2}-\d{2}$/.test(trimmed)) return `${trimmed}T00:00:00.000Z`;
	const parsed = Date.parse(trimmed);
	if (Number.isNaN(parsed)) throw new OntologyError(`invalid timestamp ${JSON.stringify(value)}; use ISO 8601 or YYYY-MM-DD`, "BAD_INPUT");
	return new Date(parsed).toISOString();
}

/**
 * Open (and migrate) the database.
 * @param {string} filePath - database path or `:memory:`.
 * @returns {{db: DatabaseSync, path: string}} store handle.
 */
export function openStore(filePath) {
	const db = new DatabaseSync(filePath);
	try {
		// WAL is the default and gives readers a consistent snapshot. Some
		// filesystems cannot host `-wal`/`-shm`; fall back instead of losing the
		// whole store (the spark probe recorded this on-device).
		try {
			db.exec("PRAGMA journal_mode = WAL");
		} catch {
			db.exec("PRAGMA journal_mode = DELETE");
		}
		db.exec("PRAGMA synchronous = NORMAL");
		db.exec("PRAGMA foreign_keys = ON");
		// The temporal schema is a hard break: no in-place migration is needed
		// here, and this store is small enough to rebuild. Check before running
		// SCHEMA, because the new indexes reference valid_from and would fail
		// on the old fact table.
		const hasFact = db.prepare("SELECT name FROM sqlite_master WHERE type = 'table' AND name = 'fact'").get() !== undefined;
		if (hasFact) {
			const factColumns = db.prepare("PRAGMA table_info(fact)").all().map((row) => String(row.name));
			if (!factColumns.includes("valid_from")) {
				db.exec("DROP TABLE IF EXISTS fact; DROP TABLE IF EXISTS entity; DROP TABLE IF EXISTS meta;");
			}
		}
		db.exec(SCHEMA);
		ensureColumns(db);
		db.exec(VIEWS);
		ensureSelf(db);
		if (readMeta(db, "version") === null) setMeta(db, "version", "0");
		setMeta(db, "schema_version", "3");
		return { db, path: filePath };
	} catch (error) {
		try {
			db.close();
		} catch {
			/* already closed */
		}
		throw error;
	}
}

/**
 * Close a store.
 * @param {{db: DatabaseSync} | null} store - handle from {@link openStore}.
 */
export function closeStore(store) {
	try {
		store?.db.close();
	} catch {
		/* disposal must not throw */
	}
}

/**
 * Seed the user's own entity exactly once.
 * @param {DatabaseSync} db - open database.
 */
function ensureSelf(db) {
	db.prepare(
		"INSERT INTO entity(id, kind, name, aliases, created_at) VALUES('self', 'self', '我', '[]', ?) ON CONFLICT(id) DO NOTHING",
	).run(nowIso());
}

/**
 * @param {DatabaseSync} db - open database.
 * @param {string} key - meta key.
 * @returns {string | null} value or null.
 */
function readMeta(db, key) {
	const row = db.prepare("SELECT value FROM meta WHERE key = ?").get(key);
	return row === undefined ? null : String(row.value);
}

/**
 * @param {DatabaseSync} db - open database.
 * @param {string} key - meta key.
 * @param {string} value - value to store.
 */
function setMeta(db, key, value) {
	db.prepare(
		"INSERT INTO meta(key, value) VALUES(?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
	).run(key, value);
}

/**
 * Additive v3 columns. v2 dropped and rebuilt the table (a hard break); v3
 * must not: `ALTER TABLE ADD COLUMN` keeps every fact and every history row.
 * Each DDL string is a constant, so this is safe to run on every open.
 * @param {DatabaseSync} db - open database.
 */
function ensureColumns(db) {
	const columns = new Set(db.prepare("PRAGMA table_info(fact)").all().map((row) => String(row.name)));
	const additions = [
		["source_kind", "source_kind TEXT NOT NULL DEFAULT 'model'"],
		["source_ref", "source_ref TEXT"],
		["status", "status TEXT NOT NULL DEFAULT 'asserted'"],
		["confirmed_at", "confirmed_at TEXT"],
	];
	for (const [name, ddl] of additions) {
		if (!columns.has(name)) db.exec(`ALTER TABLE fact ADD COLUMN ${ddl}`);
	}
	// Existing rows only have the coarse `source`; preserve what it can tell us.
	db.exec(`
		UPDATE fact
		SET source_kind = CASE source
			WHEN 'migrated' THEN 'migration'
			WHEN 'import' THEN 'import'
			ELSE 'model'
		END
		WHERE source_kind = 'model' AND source IN ('migrated', 'import')
	`);
}

/**
 * @param {{db: DatabaseSync}} store - store handle.
 * @returns {number} monotonically increasing content version.
 */
export function getVersion(store) {
	return Number(readMeta(store.db, "version") ?? "0");
}

/**
 * @param {{db: DatabaseSync}} store - store handle.
 * @returns {number} the new version.
 */
function bumpVersion(store) {
	const next = getVersion(store) + 1;
	setMeta(store.db, "version", String(next));
	return next;
}

/**
 * Resolve a name/id to a live entity, creating one when the name is new.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} token - entity id, `self`, or display name.
 * @param {string} [kindHint] - entity kind for a new entity.
 * @returns {{id: string, kind: string, name: string}} entity row.
 */
export function resolveEntity(store, token, kindHint = "other") {
	const value = String(token ?? "").trim();
	if (value.length === 0) throw new OntologyError("subject/object entity name is empty", "BAD_INPUT");
	if (value.length > 100) throw new OntologyError("entity name is longer than 100 characters", "BAD_INPUT");
	if (value === "self") {
		const row = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = 'self'").get();
		return { id: row.id, kind: row.kind, name: row.name };
	}
	if (value.startsWith("ent_")) {
		const row = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = ? AND merged_into IS NULL").get(value);
		if (row === undefined) throw new OntologyError(`unknown entity id ${value}`, "UNKNOWN_ENTITY");
		return { id: row.id, kind: row.kind, name: row.name };
	}
	const wanted = value.toLowerCase();
	for (const row of store.db.prepare("SELECT id, kind, name, aliases FROM entity WHERE merged_into IS NULL").all()) {
		if (String(row.name).toLowerCase() === wanted) return { id: row.id, kind: row.kind, name: row.name };
		try {
			const aliases = JSON.parse(String(row.aliases));
			if (Array.isArray(aliases) && aliases.some((alias) => String(alias).toLowerCase() === wanted)) {
				return { id: row.id, kind: row.kind, name: row.name };
			}
		} catch {
			/* a hand-edited alias list must not break resolution */
		}
	}
	const kind = ENTITY_KINDS.includes(kindHint) ? kindHint : "other";
	const id = newId("ent");
	store.db.prepare("INSERT INTO entity(id, kind, name, aliases, created_at) VALUES(?, ?, ?, '[]', ?)").run(id, kind, value, nowIso());
	return { id, kind, name: value };
}

/**
 * Find an entity without creating one.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} token - id or name.
 * @returns {{id: string, kind: string, name: string} | null} entity or null.
 */
export function findEntity(store, token) {
	const value = String(token ?? "").trim();
	if (value.length === 0) return null;
	if (value === "self") {
		const row = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = 'self'").get();
		return row === undefined ? null : { id: row.id, kind: row.kind, name: row.name };
	}
	const byId = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = ? AND merged_into IS NULL").get(value);
	if (byId !== undefined) return { id: byId.id, kind: byId.kind, name: byId.name };
	const wanted = value.toLowerCase();
	for (const row of store.db.prepare("SELECT id, kind, name, aliases FROM entity WHERE merged_into IS NULL").all()) {
		if (String(row.name).toLowerCase() === wanted) return { id: row.id, kind: row.kind, name: row.name };
		try {
			const aliases = JSON.parse(String(row.aliases));
			if (Array.isArray(aliases) && aliases.some((alias) => String(alias).toLowerCase() === wanted)) {
				return { id: row.id, kind: row.kind, name: row.name };
			}
		} catch {
			/* ignore malformed aliases */
		}
	}
	return null;
}

/**
 * Project a joined row into the model/UI shape.
 * @param {any} row - row from {@link SELECT_FACT}.
 * @returns {object} public fact.
 */
export function publicFact(row) {
	const isEntity = row.object_kind === "entity";
	return {
		id: String(row.id),
		subject: String(row.subject_name),
		subject_id: String(row.subject),
		predicate: String(row.predicate),
		object: isEntity ? String(row.object_name ?? row.object ?? "") : String(row.object ?? ""),
		object_id: isEntity ? String(row.object) : null,
		object_kind: String(row.object_kind),
		qualifier: row.qualifier === null || row.qualifier === undefined ? "" : String(row.qualifier),
		confidence: Number(row.confidence),
		source: String(row.source),
		source_kind: String(row.source_kind ?? "model"),
		source_ref: row.source_ref === null || row.source_ref === undefined ? null : String(row.source_ref),
		status: String(row.status ?? "asserted"),
		confirmed_at: row.confirmed_at === null || row.confirmed_at === undefined ? null : String(row.confirmed_at),
		observed_at: String(row.observed_at),
		valid_from: String(row.valid_from ?? row.observed_at),
		valid_to: row.valid_to === null || row.valid_to === undefined ? null : String(row.valid_to),
		recorded_at: String(row.recorded_at ?? row.observed_at),
		superseded_by: row.superseded_by === null || row.superseded_by === undefined ? null : String(row.superseded_by),
		superseded_at: row.superseded_at === null || row.superseded_at === undefined ? null : String(row.superseded_at),
		retired_at: row.retired_at === null || row.retired_at === undefined ? null : String(row.retired_at),
		pinned: row.pinned === 1,
	};
}

/**
 * Read one fact by id.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} id - fact id.
 * @returns {object | null} public fact.
 */
export function getFact(store, id) {
	const row = store.db.prepare(`${SELECT_FACT} WHERE f.id = ?`).get(id);
	return row === undefined ? null : publicFact(row);
}


/**
 * Insert one fact with valid-time ordering. For a single-valued predicate,
 * a later `valid_from` replaces the current row; an earlier `valid_from` is
 * stored as a closed historical row (it never becomes live).
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{subjectId: string, predicate: string, spec: object, object: string,
 *   objectKind: string, qualifier: string, confidence: number, source: string,
 *   sourceKind?: string, sourceRef?: string|null, status?: string,
 *   observedAt: string, validFrom: string, recordedAt: string, pinned: boolean}} input - row.
 * @returns {{fact: object, duplicate: boolean, superseded: string[], historical: boolean}} outcome.
 */
function insertTemporalFact(store, input) {
	const current = input.spec.cardinality === "one"
		? store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ?`)
			.get(input.subjectId, input.predicate)
		: undefined;
	const status = input.status === "proposed" ? "proposed" : "asserted";
	const historical = status !== "proposed" && current !== undefined && (input.validFrom < String(current.valid_from)
		|| (input.validFrom === String(current.valid_from) && input.localWrite !== true && input.recordedAt <= String(current.recorded_at)));
	const id = newId("fact");
	const sourceKind = String(input.sourceKind ?? "model").slice(0, 20) || "model";
	const sourceRef = input.sourceRef === null || input.sourceRef === undefined
		? null
		: String(input.sourceRef).slice(0, 200);
	const confirmedAt = status === "proposed"
		? null
		: (input.confirmedAt ?? (sourceKind === "user" ? input.recordedAt : null));
	store.db.prepare(
		"INSERT INTO fact(id, subject, predicate, object, object_kind, qualifier, confidence, source, source_kind, source_ref, status, confirmed_at, observed_at, valid_from, valid_to, recorded_at, superseded_by, superseded_at, pinned) VALUES(?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
	).run(
		id,
		input.subjectId,
		input.predicate,
		input.object,
		input.objectKind,
		input.qualifier.length === 0 ? null : input.qualifier,
		input.confidence,
		input.source,
		sourceKind,
		sourceRef,
		status,
		confirmedAt,
		input.observedAt,
		input.validFrom,
		historical ? String(current.valid_from) : null,
		input.recordedAt,
		historical ? String(current.id) : null,
		historical ? input.recordedAt : null,
		input.pinned ? 1 : 0,
	);
	const superseded = [];
	if (status !== "proposed" && current !== undefined && !historical) {
		const end = input.validFrom > String(current.valid_from) ? input.validFrom : String(current.valid_from);
		store.db.prepare(
			"UPDATE fact SET superseded_by = ?, superseded_at = ?, valid_to = ? WHERE id = ?",
		).run(id, input.recordedAt, end, current.id);
		superseded.push(String(current.id));
	}
	return { fact: getFact(store, id), duplicate: false, superseded, historical };
}

/**
 * Validate and insert a fact.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{
 *   subject: string, predicate: string, object: string|number|boolean,
 *   qualifier?: string, confidence?: number, source?: string, observedAt?: string,
 *   sourceKind?: string, sourceRef?: string|null, status?: string,
 *   preserveNewer?: boolean,
 * }} input - assert input.
 * @returns {{fact: object, duplicate: boolean, superseded: string[]}} outcome.
 */
export function remember(store, input) {
	const predicate = String(input.predicate ?? "").trim();
	const spec = predicateSpec(predicate);
	if (spec === null) {
		const guesses = suggestPredicate(predicate);
		const hint = guesses.length > 0 ? `; did you mean ${guesses.join(" / ")}?` : "";
		throw new OntologyError(`unknown predicate ${JSON.stringify(predicate)}${hint}; use one of the documented predicates`, "UNKNOWN_PREDICATE");
	}
	const subject = resolveEntity(store, input.subject, input.subject === "self" ? "self" : "other");
	const qualifier = String(input.qualifier ?? "").trim();
	if (spec.qualifier === "required" && qualifier.length === 0) {
		throw new OntologyError(`predicate ${predicate} requires a qualifier (the role, e.g. mother/friend/client)`, "BAD_INPUT");
	}
	if (qualifier.length > 100) throw new OntologyError("qualifier is longer than 100 characters", "BAD_INPUT");

	let object;
	let objectKind;
	if (spec.kind === "entity") {
		const entity = resolveEntity(store, input.object, spec.entityKind ?? "other");
		object = entity.id;
		objectKind = "entity";
	} else if (spec.kind === "date") {
		object = normalizeDate(String(input.object ?? ""));
		objectKind = "date";
	} else {
		object = String(input.object ?? "").trim();
		if (object.length === 0) throw new OntologyError("object is required", "BAD_INPUT");
		if (object.length > 500) throw new OntologyError("object is longer than 500 characters", "BAD_INPUT");
		objectKind = spec.kind;
	}

	const now = nowIso();
	const observedAt = normalizeInstant(input.observedAt, now);
	const validFrom = normalizeInstant(input.validFrom ?? input.effectiveAt ?? input.effective_at, observedAt);
	const recordedAt = normalizeInstant(input.recordedAt, now);

	const existing = store.db
		.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ? AND f.object = ? AND COALESCE(f.qualifier, '') = ?`)
		.get(subject.id, predicate, object, qualifier);
	if (existing !== undefined) {
		return { fact: publicFact(existing), duplicate: true, superseded: [], historical: false };
	}
	if (input.status === "proposed") {
		const pending = store.db
			.prepare(`${SELECT_FACT} WHERE f.subject = ? AND f.predicate = ? AND f.object = ? AND COALESCE(f.qualifier, '') = ? AND f.status = 'proposed' AND f.retired_at IS NULL`)
			.get(subject.id, predicate, object, qualifier);
		if (pending !== undefined) {
			return { fact: publicFact(pending), duplicate: true, superseded: [], historical: false };
		}
	}

	// Migration uses this: a historical profile line must not supersede a
	// value the user asserted later.
	if (input.preserveNewer === true && spec.cardinality === "one") {
		const current = store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ?`)
			.get(subject.id, predicate);
		if (current !== undefined && String(current.valid_from) >= validFrom) {
			return { fact: publicFact(current), duplicate: true, superseded: [], historical: false, skipped: true };
		}
	}

	const sourceKind = String(input.sourceKind ?? "model").slice(0, 20) || "model";
	const outcome = insertTemporalFact(store, {
		subjectId: subject.id,
		predicate,
		spec,
		object,
		objectKind,
		qualifier,
		confidence: Math.min(1, Math.max(0, Number(input.confidence ?? 1))),
		source: String(input.source ?? (sourceKind === "migration" ? "migrated" : sourceKind)).trim().slice(0, 40) || "model",
		sourceKind,
		sourceRef: input.sourceRef,
		status: input.status,
		observedAt,
		validFrom,
		recordedAt,
		pinned: spec.pinned,
		localWrite: true,
	});
	// A concrete assertion supersedes a pending candidate with the same identity;
	// otherwise the queue would keep showing a fact the user just confirmed.
	if (input.status !== "proposed") {
		store.db
			.prepare("DELETE FROM fact WHERE subject = ? AND predicate = ? AND object = ? AND COALESCE(qualifier, '') = ? AND status = 'proposed'")
			.run(subject.id, predicate, object, qualifier);
	}
	bumpVersion(store);
	return outcome;
}

/**
 * Write a candidate that must be confirmed in the panel before it can be
 * injected or searched. Never use this for something the user stated directly.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {object} input - same shape as {@link remember}.
 * @returns {object} outcome with a `status: "proposed"` fact.
 */
export function propose(store, input) {
	return remember(store, {
		...input,
		status: "proposed",
		sourceKind: input.sourceKind ?? "model",
	});
}

/**
 * Proposed facts, newest first. A candidate whose identity is already live is
 * hidden: it is waiting for nothing.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {number} [limit] - maximum rows.
 * @returns {object[]} public facts with `status: "proposed"`.
 */
export function pendingFacts(store, limit = 50) {
	const rows = store.db
		.prepare(`${SELECT_FACT} WHERE f.status = 'proposed' AND f.retired_at IS NULL AND f.superseded_by IS NULL ORDER BY f.observed_at DESC LIMIT ?`)
		.all(Math.min(200, Math.max(1, limit)));
	const live = new Set(
		store.db
			.prepare("SELECT subject, predicate, object, COALESCE(qualifier, '') AS q FROM v_live_fact")
			.all()
			.map((row) => `${row.subject}|${row.predicate}|${row.object}|${row.q}`),
	);
	return rows
		.filter((row) => !live.has(`${row.subject}|${row.predicate}|${row.object}|${row.qualifier ?? ""}`))
		.map(publicFact);
}

/**
 * Promote a proposed fact to asserted. For single-valued predicates this also
 * closes the current live interval, using the same valid-time rules as
 * `remember`; an older candidate becomes history instead of overwriting.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} factId - proposed fact id.
 * @returns {{fact: object, superseded: string[], duplicate: boolean, historical: boolean}} outcome.
 */
export function confirmProposed(store, factId) {
	const proposed = getFact(store, String(factId ?? ""));
	if (proposed === null) throw new OntologyError(`fact not found: ${factId}`, "NOT_FOUND");
	if (proposed.status !== "proposed") throw new OntologyError("fact is not proposed", "BAD_INPUT");
	const spec = predicateSpec(proposed.predicate);
	if (spec === null) throw new OntologyError(`predicate ${proposed.predicate} is no longer in the vocabulary`, "UNKNOWN_PREDICATE");
	const now = nowIso();
	const proposedValue = proposed.object_kind === "entity" ? String(proposed.object_id) : String(proposed.object);
	const superseded = [];
	if (spec.cardinality === "one") {
		const current = store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ?`)
			.get(proposed.subject_id, proposed.predicate);
		if (current !== undefined) {
			const sameValue = String(current.object) === proposedValue
				&& String(current.qualifier ?? "") === proposed.qualifier;
			if (sameValue) {
				store.db.prepare("DELETE FROM fact WHERE id = ?").run(proposed.id);
				bumpVersion(store);
				return { fact: publicFact(current), superseded: [], duplicate: true, historical: false };
			}
			if (proposed.valid_from >= String(current.valid_from)) {
				store.db
					.prepare("UPDATE fact SET superseded_by = ?, superseded_at = ?, valid_to = ? WHERE id = ?")
					.run(proposed.id, now, proposed.valid_from, current.id);
				superseded.push(String(current.id));
			} else {
				store.db
					.prepare("UPDATE fact SET status = 'asserted', confirmed_at = ?, superseded_by = ?, superseded_at = ?, valid_to = ? WHERE id = ?")
					.run(now, current.id, now, current.valid_from, proposed.id);
				bumpVersion(store);
				return { fact: getFact(store, proposed.id), superseded: [], duplicate: false, historical: true };
			}
		}
	}
	store.db.prepare("UPDATE fact SET status = 'asserted', confirmed_at = ? WHERE id = ?").run(now, proposed.id);
	bumpVersion(store);
	return { fact: getFact(store, proposed.id), superseded, duplicate: false, historical: false };
}

/**
 * Drop a proposed candidate permanently. It was never live, so there is no
 * history to preserve.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} factId - proposed fact id.
 * @returns {{id: string}} removed fact id.
 */
export function rejectProposed(store, factId) {
	const proposed = getFact(store, String(factId ?? ""));
	if (proposed === null) throw new OntologyError(`fact not found: ${factId}`, "NOT_FOUND");
	if (proposed.status !== "proposed") throw new OntologyError("fact is not proposed", "BAD_INPUT");
	store.db.prepare("DELETE FROM fact WHERE id = ?").run(proposed.id);
	bumpVersion(store);
	return { id: proposed.id };
}

/**
 * Replace the object of an existing fact (history preserved).
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{factId: string, object: string|number|boolean, qualifier?: string, source?: string,
 *   sourceKind?: string, sourceRef?: string|null}} input - correction.
 * @returns {{fact: object, replaced: object, superseded: string[]}} outcome.
 */
export function correct(store, input) {
	const old = getFact(store, String(input.factId ?? ""));
	if (old === null) throw new OntologyError(`fact not found: ${input.factId}`, "NOT_FOUND");
	if (old.status === "proposed") throw new OntologyError("fact is still proposed; confirm it before correcting", "BAD_INPUT");
	if (old.superseded_by !== null || old.retired_at !== null) {
		throw new OntologyError("fact is no longer live; correct the current value instead", "BAD_INPUT");
	}
	const spec = predicateSpec(old.predicate);
	if (spec === null) throw new OntologyError(`predicate ${old.predicate} is no longer in the vocabulary`, "UNKNOWN_PREDICATE");
	const qualifier = String(input.qualifier ?? old.qualifier).trim();
	if (spec.qualifier === "required" && qualifier.length === 0) {
		throw new OntologyError(`predicate ${old.predicate} requires a qualifier`, "BAD_INPUT");
	}
	let object;
	let objectKind;
	if (spec.kind === "entity") {
		const entity = resolveEntity(store, input.object, spec.entityKind ?? "other");
		object = entity.id;
		objectKind = "entity";
	} else if (spec.kind === "date") {
		object = normalizeDate(String(input.object ?? ""));
		objectKind = "date";
	} else {
		object = String(input.object ?? "").trim();
		if (object.length === 0) throw new OntologyError("object is required", "BAD_INPUT");
		if (object.length > 500) throw new OntologyError("object is longer than 500 characters", "BAD_INPUT");
		objectKind = spec.kind;
	}
	const now = nowIso();
	const sourceKind = String(input.sourceKind ?? "model").slice(0, 20) || "model";
	const outcome = insertTemporalFact(store, {
		subjectId: old.subject_id,
		predicate: old.predicate,
		spec,
		object,
		objectKind,
		qualifier,
		confidence: old.confidence,
		source: String(input.source ?? sourceKind).trim().slice(0, 40) || "model",
		sourceKind,
		sourceRef: input.sourceRef,
		status: "asserted",
		observedAt: now,
		validFrom: normalizeInstant(input.effectiveAt ?? input.effective_at, now),
		recordedAt: now,
		pinned: old.pinned,
		localWrite: true,
	});
	bumpVersion(store);
	return { fact: outcome.fact, replaced: old, superseded: outcome.superseded, historical: outcome.historical };
}

/**
 * Retire facts (soft by default; `hard` deletes the rows).
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{factId?: string, query?: string, subject?: string, predicate?: string, hard?: boolean}} input - selector.
 * @returns {{count: number, ids: string[], hard: boolean}} outcome.
 */
export function forget(store, input) {
	const ids = [];
	const hard = input.hard === true;
	if (input.factId !== undefined && String(input.factId).trim().length > 0) {
		const row = store.db.prepare("SELECT id FROM fact WHERE id = ?").get(String(input.factId).trim());
		if (row === undefined) throw new OntologyError(`fact not found: ${input.factId}`, "NOT_FOUND");
		ids.push(String(row.id));
	} else {
		const where = ["f.superseded_by IS NULL", "f.retired_at IS NULL"];
		const args = [];
		if (input.predicate !== undefined && String(input.predicate).trim().length > 0) {
			where.push("f.predicate = ?");
			args.push(String(input.predicate).trim());
		}
		if (input.subject !== undefined && String(input.subject).trim().length > 0) {
			const entity = findEntity(store, input.subject);
			if (entity === null) return { count: 0, ids: [], hard };
			where.push("f.subject = ?");
			args.push(entity.id);
		}
		if (input.query !== undefined && String(input.query).trim().length > 0) {
			const like = `%${String(input.query).trim()}%`;
			where.push("(s.name LIKE ? OR f.object LIKE ? OR f.qualifier LIKE ? OR f.predicate LIKE ?)");
			args.push(like, like, like, like);
		}
		for (const row of store.db
			.prepare(`SELECT f.id FROM fact f JOIN entity s ON s.id = f.subject WHERE ${where.join(" AND ")} LIMIT 200`)
			.all(...args)) {
			ids.push(String(row.id));
		}
	}
	if (ids.length === 0) return { count: 0, ids: [], hard };
	for (const id of ids) {
		if (hard) store.db.prepare("DELETE FROM fact WHERE id = ?").run(id);
		else store.db.prepare("UPDATE fact SET retired_at = ?, valid_to = COALESCE(valid_to, ?) WHERE id = ?").run(nowIso(), nowIso(), id);
	}
	bumpVersion(store);
	return { count: ids.length, ids, hard };
}

/**
 * Search live (or all) facts.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{query?: string, subject?: string, predicate?: string, limit?: number, history?: boolean}} input - filters.
 * @returns {object[]} public facts.
 */
export function search(store, input) {
	const history = input.history === true;
	const where = [];
	const args = [];
	if (input.predicate !== undefined && String(input.predicate).trim().length > 0) {
		where.push("f.predicate = ?");
		args.push(String(input.predicate).trim());
	}
	if (input.subject !== undefined && String(input.subject).trim().length > 0) {
		const entity = findEntity(store, input.subject);
		if (entity === null) return [];
		where.push("f.subject = ?");
		args.push(entity.id);
	}
	if (input.query !== undefined && String(input.query).trim().length > 0) {
		const raw = String(input.query).trim();
		const like = `%${raw}%`;
		// Natural-language queries ("我对什么过敏") should hit the controlled
		// predicate even when the literal word is not in subject/object. Synonym
		// expansion stays lexical: no embedding model on the device.
		const expanded = input.predicate === undefined ? predicatesMatching(raw) : [];
		if (expanded.length === 0) {
			where.push("(s.name LIKE ? OR f.object LIKE ? OR f.qualifier LIKE ? OR f.predicate LIKE ? OR o.name LIKE ?)");
			args.push(like, like, like, like, like);
		} else {
			const placeholders = expanded.map(() => "?").join(", ");
			where.push(`(s.name LIKE ? OR f.object LIKE ? OR f.qualifier LIKE ? OR f.predicate LIKE ? OR o.name LIKE ? OR f.predicate IN (${placeholders}))`);
			args.push(like, like, like, like, like, ...expanded);
		}
	}
	const limit = Math.min(100, Math.max(1, Number(input.limit ?? 20)));
	const clause = where.length === 0 ? "" : `WHERE ${where.join(" AND ")}`;
	const base = history ? SELECT_FACT : SELECT_LIVE_FACT;
	const rows = store.db
		.prepare(`${base} ${clause} ORDER BY f.pinned DESC, f.observed_at DESC LIMIT ?`)
		.all(...args, limit);
	return rows.map(publicFact);
}

/**
 * Walk the entity graph from one node.
 *
 * The graph is small (a person, their people, projects, and organizations), so
 * a breadth-first walk in JavaScript is cheaper than a recursive CTE and much
 * easier to cap. `depth` is deliberately limited to 2: "my mother's allergy"
 * is useful; "everything within six hops" is a privacy leak and a prompt bomb.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {{entity?: string, depth?: number, predicates?: string[]|string, limit?: number}} input - walk.
 * @returns {{root: object, nodes: object[], truncated: boolean}} graph slice.
 */
export function related(store, input) {
	const token = String(input.entity ?? "self").trim() || "self";
	const root = findEntity(store, token);
	if (root === null) throw new OntologyError(`unknown entity ${JSON.stringify(token)}`, "UNKNOWN_ENTITY");
	const depth = Math.min(2, Math.max(1, Number(input.depth ?? 1)));
	const maxNodes = Math.min(50, Math.max(1, Number(input.limit ?? 20)));
	const predicates = (Array.isArray(input.predicates) ? input.predicates : String(input.predicates ?? "").split(","))
		.map((predicate) => String(predicate).trim())
		.filter((predicate) => predicate.length > 0);
	const nodes = [];
	const visited = new Set();
	const queue = [{ id: root.id, depth: 0 }];
	while (queue.length > 0 && nodes.length < maxNodes) {
		const current = queue.shift();
		if (visited.has(current.id)) continue;
		visited.add(current.id);
		const entity = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = ?").get(current.id);
		if (entity === undefined) continue;
		const facts = store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? ORDER BY f.pinned DESC, f.observed_at DESC`)
			.all(current.id)
			.map(publicFact)
			.filter((fact) => predicates.length === 0 || predicates.includes(fact.predicate));
		const edges = [];
		for (const edge of store.db
			.prepare("SELECT from_id, predicate, to_id, qualifier FROM v_entity_edge WHERE from_id = ? OR to_id = ?")
			.all(current.id, current.id)) {
			const predicate = String(edge.predicate);
			if (predicates.length > 0 && !predicates.includes(predicate)) continue;
			const outgoing = String(edge.from_id) === current.id;
			const otherId = outgoing ? String(edge.to_id) : String(edge.from_id);
			const other = store.db.prepare("SELECT id, kind, name FROM entity WHERE id = ?").get(otherId);
			if (other === undefined) continue;
			edges.push({
				predicate,
				direction: outgoing ? "out" : "in",
				qualifier: edge.qualifier === null || edge.qualifier === undefined ? "" : String(edge.qualifier),
				other: { id: String(other.id), kind: String(other.kind), name: String(other.name) },
			});
			if (current.depth < depth && !visited.has(otherId)) {
				queue.push({ id: otherId, depth: current.depth + 1 });
			}
		}
		nodes.push({
			entity: { id: String(entity.id), kind: String(entity.kind), name: String(entity.name) },
			facts,
			edges,
		});
	}
	return {
		root: { id: root.id, kind: root.kind, name: root.name },
		nodes,
		truncated: queue.length > 0 || nodes.length >= maxNodes,
	};
}

/**
 * Counts + pinned + recent, for the panel and the `list` action.
 * @param {{db: DatabaseSync}} store - store handle.
 * @returns {{counts: object, pinned: object[], recent: object[], version: number}} summary.
 */
export function overview(store) {
	const facts = Number(store.db.prepare("SELECT COUNT(*) AS n FROM v_live_fact").get().n);
	const entities = Number(store.db.prepare("SELECT COUNT(*) AS n FROM entity WHERE merged_into IS NULL").get().n);
	const pinned = Number(store.db.prepare("SELECT COUNT(*) AS n FROM v_live_fact WHERE pinned = 1").get().n);
	const pending = pendingFacts(store, 200).length;
	const pinnedRows = store.db
		.prepare(`${SELECT_LIVE_FACT} WHERE f.pinned = 1 ORDER BY f.observed_at DESC`)
		.all()
		.map(publicFact);
	const recentRows = store.db
		.prepare(`${SELECT_LIVE_FACT} ORDER BY f.observed_at DESC LIMIT 10`)
		.all()
		.map(publicFact);
	return { counts: { facts, entities, pinned, pending }, pinned: pinnedRows, recent: recentRows, version: getVersion(store) };
}

/**
 * Every live fact, bounded for the snapshot/export path.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {number} [limit] - maximum rows.
 * @returns {object[]} public facts.
 */
export function liveFacts(store, limit = 400) {
	const rows = store.db
		.prepare(`${SELECT_LIVE_FACT} ORDER BY f.pinned DESC, f.observed_at DESC LIMIT ?`)
		.all(Math.min(2000, Math.max(1, limit)));
	return rows.map(publicFact);
}

/**
 * Recent soft-deleted facts, newest first. Used by the panel's "recently
 * deleted" section so a chat receipt like "已记住" can be traced after the
 * user removes the fact.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {number} [limit] - maximum rows.
 * @returns {object[]} public facts with `retired_at`.
 */
export function deletedFacts(store, limit = 10) {
	if (limit <= 0) return [];
	const rows = store.db
		.prepare(`${SELECT_FACT} WHERE f.retired_at IS NOT NULL AND f.superseded_by IS NULL ORDER BY f.retired_at DESC LIMIT 200`)
		.all();
	const seen = new Set();
	const out = [];
	for (const row of rows) {
		const key = `${String(row.subject)}|${String(row.predicate)}|${String(row.object)}|${String(row.qualifier ?? "")}`;
		if (seen.has(key)) continue;
		seen.add(key);
		out.push({ ...publicFact(row), retired_at: String(row.retired_at) });
		if (out.length >= limit) break;
	}
	return out;
}

/**
 * Live entities, for Turtle labels and diagnostics.
 * @param {{db: DatabaseSync}} store - store handle.
 * @returns {{id: string, kind: string, name: string}[]} entities.
 */
export function listEntities(store) {
	return store.db
		.prepare("SELECT id, kind, name FROM entity WHERE merged_into IS NULL ORDER BY created_at")
		.all()
		.map((row) => ({ id: String(row.id), kind: String(row.kind), name: String(row.name) }));
}

/**
 * One fact line for tool output.
 * @param {object} fact - public fact.
 * @returns {string} compact line with id.
 */
export function factLine(fact) {
	const qualifier = fact.qualifier.length > 0 ? ` (${fact.qualifier})` : "";
	const when = String(fact.valid_from ?? fact.observed_at);
	const provenance = `${fact.source_kind ?? "model"}${fact.status === "proposed" ? "/proposed" : ""}`;
	return `${fact.subject} · ${fact.predicate} = ${fact.object}${qualifier} [${fact.id}] ${when.slice(0, 10)} · ${provenance}`;
}

/**
 * Deletion markers for sync. A tombstone carries the stable identity
 * (subject name + predicate + object + qualifier) and the deletion time, not a
 * device-local fact id, so the receiver can find its own copy.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {number} [limit] - maximum rows.
 * @returns {object[]} tombstones.
 */
export function tombstones(store, limit = 2000) {
	return store.db
		.prepare(`${SELECT_FACT} WHERE f.retired_at IS NOT NULL AND f.superseded_by IS NULL ORDER BY f.retired_at DESC LIMIT ?`)
		.all(limit)
		.map((row) => {
			const isEntity = row.object_kind === "entity";
			return {
				subject_name: String(row.subject_name),
				subject_kind: String(row.subject_kind),
				predicate: String(row.predicate),
				object: isEntity ? String(row.object_name ?? "") : String(row.object ?? ""),
				object_kind: String(row.object_kind),
				object_name: isEntity ? String(row.object_name ?? "") : null,
				qualifier: row.qualifier === null || row.qualifier === undefined ? "" : String(row.qualifier),
				valid_from: String(row.valid_from ?? row.observed_at),
				recorded_at: String(row.recorded_at ?? row.observed_at),
				retired_at: String(row.retired_at),
			};
		});
}

/**
 * Soft-retire one fact at the tombstone's timestamp. Returns false when the
 * fact is already retired/superseded or unknown.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {string} factId - local fact id.
 * @param {string} retiredAt - deletion timestamp from the tombstone.
 * @returns {boolean} whether a row changed.
 */
export function retireAt(store, factId, retiredAt) {
	const result = store.db
		.prepare("UPDATE fact SET retired_at = ?, valid_to = COALESCE(valid_to, ?) WHERE id = ? AND retired_at IS NULL AND superseded_by IS NULL")
		.run(String(retiredAt), String(retiredAt), String(factId));
	return Number(result.changes ?? 0) > 0;
}

/**
 * Export a portable, mergeable bundle of the live ontology.
 *
 * The SQLite file itself is not a sync unit: it is open in this process, has
 * WAL side files, and a whole-file replace cannot merge the receiver's own
 * facts. The bundle is the interchange format: entity ids are hints, names and
 * aliases are the real identity, and each fact carries its own observed_at so
 * the merge can tell which side is newer.
 * @param {{db: DatabaseSync}} store - store handle.
 * @returns {object} bundle.
 */
export function exportBundle(store) {
	const entities = store.db
		.prepare("SELECT id, kind, name, aliases, created_at FROM entity WHERE merged_into IS NULL ORDER BY created_at")
		.all()
		.map((row) => {
			let aliases = [];
			try {
				const parsed = JSON.parse(String(row.aliases));
				if (Array.isArray(parsed)) aliases = parsed.map((alias) => String(alias));
			} catch {
				/* malformed aliases are not worth failing an export */
			}
			return {
				id: String(row.id),
				kind: String(row.kind),
				name: String(row.name),
				aliases,
			};
		});
	const facts = store.db
		.prepare(`${SELECT_LIVE_FACT} ORDER BY f.observed_at`)
		.all()
		.map((row) => ({
			id: String(row.id),
			subject: String(row.subject),
			subject_name: String(row.subject_name),
			predicate: String(row.predicate),
			object: String(row.object ?? ""),
			object_kind: String(row.object_kind),
			object_id: row.object_kind === "entity" ? String(row.object) : null,
			object_name: row.object_kind === "entity" ? String(row.object_name ?? "") : null,
			qualifier: row.qualifier === null || row.qualifier === undefined ? "" : String(row.qualifier),
			confidence: Number(row.confidence),
			source: String(row.source),
			source_kind: String(row.source_kind ?? "model"),
			source_ref: row.source_ref === null || row.source_ref === undefined ? null : String(row.source_ref),
			status: String(row.status ?? "asserted"),
			confirmed_at: row.confirmed_at === null || row.confirmed_at === undefined ? null : String(row.confirmed_at),
			observed_at: String(row.observed_at),
			valid_from: String(row.valid_from ?? row.observed_at),
			valid_to: row.valid_to === null || row.valid_to === undefined ? null : String(row.valid_to),
			recorded_at: String(row.recorded_at ?? row.observed_at),
		}));
	return {
		format: "harmonygo-ontology-bundle",
		version: 1,
		exportedAt: nowIso(),
		vocabulary: [...PREDICATE_NAMES],
		entities,
		facts,
		tombstones: tombstones(store, 2000),
	};
}

/**
 * Merge a bundle exported by {@link exportBundle} into this store.
 *
 * v1 is a live-fact merge: deletions are soft (`retired_at`) and are not
 * propagated, so a fact deleted on one device can come back from the other.
 * That is deliberate and documented; tombstone sync is a later format version.
 * @param {{db: DatabaseSync}} store - store handle.
 * @param {any} bundle - parsed bundle.
 * @param {{sourceRef?: string}} [options] - where the bundle came from.
 * @returns {{entitiesCreated: number, imported: number, skipped: number, superseded: number,
 *   historical: number, retracted: number, conflicts: object[]}} outcome.
 */
export function importBundle(store, bundle, options = {}) {
	if (bundle === null || typeof bundle !== "object") throw new OntologyError("bundle is not an object", "BAD_INPUT");
	if (bundle.format !== "harmonygo-ontology-bundle") {
		throw new OntologyError(`not an ontology bundle: ${String(bundle.format)}`, "BAD_INPUT");
	}
	if (bundle.version !== 1) {
		throw new OntologyError(`unsupported bundle version ${String(bundle.version)}`, "BAD_INPUT");
	}
	const sourceRef = String(options.sourceRef ?? "bundle").slice(0, 200);
	const counts = { entitiesCreated: 0, imported: 0, skipped: 0, superseded: 0, historical: 0, retracted: 0, conflicts: [] };
	const idMap = new Map();
	idMap.set("self", "self");
	const exists = (id) => store.db.prepare("SELECT 1 AS ok FROM entity WHERE id = ?").get(id) !== undefined;
	for (const entity of Array.isArray(bundle.entities) ? bundle.entities : []) {
		const name = String(entity?.name ?? "").trim();
		if (name.length === 0) continue;
		const incomingId = typeof entity?.id === "string" ? entity.id : "";
		const aliases = Array.isArray(entity?.aliases) ? entity.aliases.map((alias) => String(alias)).filter((alias) => alias.length > 0) : [];
		let local = findEntity(store, name);
		if (local === null && incomingId.length > 0 && incomingId !== "self") local = findEntity(store, incomingId);
		if (local === null) {
			if (name === "我" || incomingId === "self") {
				local = { id: "self", kind: "self", name: "我" };
			} else {
				const id = incomingId.length > 0 && !exists(incomingId) ? incomingId : newId("ent");
				const kind = ENTITY_KINDS.includes(entity?.kind) ? entity.kind : "other";
				store.db
					.prepare("INSERT INTO entity(id, kind, name, aliases, created_at) VALUES(?, ?, ?, ?, ?)")
					.run(id, kind, name, JSON.stringify(aliases), nowIso());
				local = { id, kind, name };
				counts.entitiesCreated++;
			}
		} else if (aliases.length > 0) {
			let current = [];
			try {
				const parsed = JSON.parse(String(store.db.prepare("SELECT aliases FROM entity WHERE id = ?").get(local.id)?.aliases ?? "[]"));
				if (Array.isArray(parsed)) current = parsed.map((alias) => String(alias));
			} catch {
				/* replace malformed aliases with the incoming set */
			}
			const merged = [...new Set([...current, ...aliases])].filter((alias) => alias !== local.name);
			store.db.prepare("UPDATE entity SET aliases = ? WHERE id = ?").run(JSON.stringify(merged), local.id);
		}
		if (incomingId.length > 0) idMap.set(incomingId, local.id);
		idMap.set(name, local.id);
	}

	for (const fact of Array.isArray(bundle.facts) ? bundle.facts : []) {
		const predicate = String(fact?.predicate ?? "").trim();
		const spec = predicateSpec(predicate);
		if (spec === null) {
			counts.skipped++;
			continue;
		}
		const subjectToken = String(fact?.subject ?? "").trim();
		const subjectName = String(fact?.subject_name ?? subjectToken).trim();
		let subjectId = idMap.get(subjectToken) ?? idMap.get(subjectName);
		if (subjectId === undefined) {
			subjectId = resolveEntity(store, subjectName.length > 0 ? subjectName : subjectToken, "other").id;
			if (subjectName.length > 0) idMap.set(subjectName, subjectId);
			if (subjectToken.length > 0) idMap.set(subjectToken, subjectId);
		}
		let object;
		let objectKind;
		let displayObject;
		if (spec.kind === "entity") {
			const incomingObjectId = typeof fact?.object_id === "string" ? fact.object_id : "";
			const objectName = String(fact?.object_name ?? fact?.object ?? "").trim();
			object = idMap.get(incomingObjectId) ?? idMap.get(objectName);
			if (object === undefined) {
				object = resolveEntity(store, objectName, spec.entityKind ?? "other").id;
				if (objectName.length > 0) idMap.set(objectName, object);
				if (incomingObjectId.length > 0) idMap.set(incomingObjectId, object);
			}
			objectKind = "entity";
			displayObject = objectName;
		} else if (spec.kind === "date") {
			try {
				object = normalizeDate(String(fact?.object ?? ""));
			} catch {
				counts.skipped++;
				continue;
			}
			objectKind = "date";
			displayObject = object;
		} else {
			object = String(fact?.object ?? "").trim();
			if (object.length === 0) {
				counts.skipped++;
				continue;
			}
			objectKind = spec.kind;
			displayObject = object;
		}
		const qualifier = String(fact?.qualifier ?? "").trim();
		if (spec.qualifier === "required" && qualifier.length === 0) {
			counts.skipped++;
			continue;
		}
		const observed = normalizeInstant(fact?.observed_at, nowIso());
		const validFrom = normalizeInstant(fact?.valid_from, observed);
		const recordedAt = normalizeInstant(fact?.recorded_at, observed);
		const duplicate = store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ? AND f.object = ? AND COALESCE(f.qualifier, '') = ?`)
			.get(subjectId, predicate, object, qualifier);
		if (duplicate !== undefined) {
			counts.skipped++;
			continue;
		}
		const current = spec.cardinality === "one"
			? store.db.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ?`).get(subjectId, predicate)
			: undefined;
		const added = insertTemporalFact(store, {
			subjectId,
			predicate,
			spec,
			object,
			objectKind,
			qualifier,
			confidence: Math.min(1, Math.max(0, Number(fact?.confidence ?? 1))),
			source: String(fact?.source ?? "import").trim().slice(0, 40) || "import",
			sourceKind: String(fact?.source_kind ?? "import").slice(0, 20) || "import",
			sourceRef: String(fact?.source_ref ?? sourceRef).slice(0, 200),
			status: "asserted",
			observedAt: observed,
			validFrom,
			recordedAt,
			pinned: spec.pinned,
			localWrite: false,
		});
		counts.imported++;
		counts.superseded += added.superseded.length;
		if (added.historical) counts.historical++;
		if (current !== undefined && String(current.object) !== String(object)) {
			counts.conflicts.push({
				predicate,
				local: publicFact(current).object,
				incoming: displayObject,
				kept: added.historical ? publicFact(current).object : added.fact.object,
				reason: added.historical
					? "local valid_from is newer"
					: validFrom === String(current.valid_from)
						? "recorded_at is newer"
						: "incoming valid_from is newer",
			});
		}
	}

	// Tombstones arrive after live facts: if the sender deleted a fact and
	// later re-added it, the re-added fact has a newer observed_at and wins.
	for (const tomb of Array.isArray(bundle.tombstones) ? bundle.tombstones : []) {
		const predicate = String(tomb?.predicate ?? "").trim();
		const spec = predicateSpec(predicate);
		if (spec === null) {
			counts.skipped++;
			continue;
		}
		const subjectName = String(tomb?.subject_name ?? "").trim();
		const subject = subjectName.length === 0 ? null : findEntity(store, subjectName);
		if (subject === null) {
			counts.skipped++;
			continue;
		}
		let object;
		let objectKind;
		if (spec.kind === "entity") {
			const objectName = String(tomb?.object_name ?? tomb?.object ?? "").trim();
			const entity = objectName.length === 0 ? null : findEntity(store, objectName);
			if (entity === null) {
				counts.skipped++;
				continue;
			}
			object = entity.id;
			objectKind = "entity";
		} else if (spec.kind === "date") {
			try {
				object = normalizeDate(String(tomb?.object ?? ""));
			} catch {
				counts.skipped++;
				continue;
			}
			objectKind = "date";
		} else {
			object = String(tomb?.object ?? "").trim();
			if (object.length === 0) {
				counts.skipped++;
				continue;
			}
			objectKind = spec.kind;
		}
		const qualifier = String(tomb?.qualifier ?? "").trim();
		if (spec.qualifier === "required" && qualifier.length === 0) {
			counts.skipped++;
			continue;
		}
		const retiredAt = String(tomb?.retired_at ?? "");
		if (retiredAt.length === 0) {
			counts.skipped++;
			continue;
		}
		const live = store.db
			.prepare(`${SELECT_LIVE_FACT} WHERE f.subject = ? AND f.predicate = ? AND f.object = ? AND COALESCE(f.qualifier, '') = ?`)
			.get(subject.id, predicate, object, qualifier);
		if (live === undefined) {
			counts.skipped++;
			continue;
		}
		if (String(live.valid_from ?? live.observed_at) > retiredAt) {
			// A newer local assertion (re-added after the deletion) wins.
			counts.skipped++;
			continue;
		}
		if (retireAt(store, String(live.id), retiredAt)) counts.retracted++;
	}
	if (counts.imported > 0 || counts.superseded > 0 || counts.retracted > 0) bumpVersion(store);
	return counts;
}
